<script setup lang="ts">
import { ref, onMounted, onUnmounted, computed } from 'vue'; import VChart from 'vue-echarts'; import { use } from 'echarts/core'; import { CanvasRenderer } from 'echarts/renderers'; import { PieChart, BarChart } from 'echarts/charts'; import { GridComponent, TooltipComponent, LegendComponent } from 'echarts/components'; import { Files, Building2, PlugZap, ListTodo, ArrowUpRight } from 'lucide-vue-next'; import { api } from '../api'; import PageHeader from '../components/PageHeader.vue'; import StatusBadge from '../components/StatusBadge.vue';
use([CanvasRenderer,PieChart,BarChart,GridComponent,TooltipComponent,LegendComponent]); const data=ref<any>({totals:{},documents_by_type:[],jobs_by_status:[],recent_jobs:[],service_health:[]}); const loading=ref(true)
async function load(){loading.value=true;try{data.value=(await api.get('/dashboard')).data}catch{}finally{loading.value=false}} onMounted(()=>{load();window.addEventListener('tenant-changed',load)});onUnmounted(()=>window.removeEventListener('tenant-changed',load))
const pie=computed(()=>({tooltip:{trigger:'item'},legend:{bottom:0},series:[{type:'pie',radius:['48%','72%'],data:data.value.documents_by_type,label:{show:false}}]})); const bar=computed(()=>({tooltip:{trigger:'axis'},grid:{left:35,right:15,top:20,bottom:45},xAxis:{type:'category',data:data.value.jobs_by_status.map((i:any)=>i.name),axisLabel:{rotate:20}},yAxis:{type:'value'},series:[{type:'bar',barMaxWidth:42,data:data.value.jobs_by_status.map((i:any)=>i.value),itemStyle:{borderRadius:[6,6,0,0]}}]}))
</script>
<template><PageHeader title="Visão geral" subtitle="Acompanhe documentos, empresas, conectores e operações fiscais em tempo real"><RouterLink class="btn primary" to="/query">Nova consulta <ArrowUpRight :size="16"/></RouterLink></PageHeader><div class="metric-grid"><div class="metric-card blue"><div><span>Documentos armazenados</span><strong>{{ data.totals.documents || 0 }}</strong><small>Cofre fiscal</small></div><Files/></div><div class="metric-card violet"><div><span>Empresas e CNPJs</span><strong>{{ data.totals.companies || 0 }}</strong><small>Estabelecimentos ativos</small></div><Building2/></div><div class="metric-card green"><div><span>Plugins ativos</span><strong>{{ data.totals.plugins || 0 }}</strong><small>Fontes configuradas</small></div><PlugZap/></div><div class="metric-card orange"><div><span>Operações pendentes</span><strong>{{ data.totals.pending_jobs || 0 }}</strong><small>Fila operacional</small></div><ListTodo/></div></div><div class="dashboard-grid"><section class="panel chart-panel"><div class="panel-title"><div><h3>Documentos por tipo</h3><p>Distribuição no cofre fiscal</p></div></div><VChart class="chart" :option="pie" autoresize /></section><section class="panel chart-panel"><div class="panel-title"><div><h3>Jobs por situação</h3><p>Estado das operações recentes</p></div></div><VChart class="chart" :option="bar" autoresize /></section><section class="panel span-2"><div class="panel-title"><div><h3>Consultas recentes</h3><p>Acompanhamento dos últimos jobs</p></div><RouterLink to="/jobs">Ver todos</RouterLink></div><div class="job-list"><div v-for="job in data.recent_jobs" :key="job.id" class="job-row"><div><strong>{{ job.access_key || 'Sincronização' }}</strong><small>{{ new Date(job.created_at).toLocaleString('pt-BR') }}</small></div><div class="progress"><i :style="{width:`${job.progress}%`}"></i></div><StatusBadge :status="job.status"/></div><div v-if="!data.recent_jobs.length" class="empty-inline">Nenhuma operação registrada.</div></div></section><section class="panel"><div class="panel-title"><div><h3>Saúde dos serviços</h3><p>Conectores instalados</p></div></div><div class="health-list"><div v-for="service in data.service_health" :key="service.name"><span><i :class="service.status"></i>{{ service.name }}</span><StatusBadge :status="service.status"/></div><div v-if="!data.service_health.length" class="empty-inline">Configure um plugin para iniciar.</div></div></section></div></template>
